import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;

final class PooledServer {
    private final ThreadPoolExecutor pool;

    PooledServer(int core, int max, int queueCap) {
        BlockingQueue<Runnable> queue = new ArrayBlockingQueue<>(queueCap);
        ThreadFactory named = new ThreadFactory() {
            private final AtomicInteger n = new AtomicInteger();
            public Thread newThread(Runnable r) {
                Thread t = new Thread(r, "worker-" + n.incrementAndGet());
                t.setDaemon(false);
                return t;
            }
        };
        // CallerRuns is backpressure: overload slows the submitter instead of OOMing.
        this.pool = new ThreadPoolExecutor(
            core, max, 30L, TimeUnit.SECONDS,
            queue, named,
            new ThreadPoolExecutor.CallerRunsPolicy());
    }

    void serve(Runnable task) {
        pool.execute(task); // throws only if shutdown; CallerRuns never silently drops
    }

    void stop() throws InterruptedException {
        pool.shutdown(); // stop accepting, drain queue
        if (!pool.awaitTermination(10, TimeUnit.SECONDS)) {
            pool.shutdownNow(); // interrupt workers; tasks must honor interrupt
            pool.awaitTermination(10, TimeUnit.SECONDS);
        }
    }
}

// WAITING releases the monitor, TIMED_WAITING via sleep does not.
// getState() is for debugging and tests, never for control flow.
final class LifecycleDemo {
    private final Object lock = new Object();
    private boolean ready;

    void awaitReady() throws InterruptedException {
        synchronized (lock) {
            while (!ready) {
                lock.wait(); // WAITING + releases lock; must loop: spurious wakeups exist
            }
        }
    }

    void signalReady() {
        synchronized (lock) {
            ready = true;
            lock.notifyAll(); // WAITING -> RUNNABLE once they reacquire lock
        }
    }

    void interruptibleWork() {
        try {
            Thread.sleep(5000); // TIMED_WAITING, keeps any held lock
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt(); // restore flag: caller must see it
            return;
        }
        if (Thread.currentThread().isInterrupted()) return;
    }
}
